solution:
class ListViewModel:
    def __init__(self):
        self.state = {"items": []}
        self.listeners = []

    def observe(self, listener):
        self.listeners.append(listener)
        listener(self.state)

    def add(self, title):
        self.state = {"items": self.state["items"] + [title]}
        for listener in self.listeners:
            listener(self.state)


def view(state):
    print("экран:", ", ".join(state["items"]) or "пусто")


vm = ListViewModel()
vm.observe(view)
for _ in range(int(input())):
    vm.add(input())

